            examples = listOf("This is my new schoolbag.", "That is a blue ruler on the table.", "Please open your book."),
            examplesVi = listOf("Đây là chiếc cặp sách mới của mình.", "Kia là chiếc thước kẻ màu xanh trên bàn.", "Làm ơn hãy mở sách của các em ra."),
