            explanation = "Add 'please' before or after actions to make requests polite.",
            explanationVi = "1. HIỆU LỆNH LỊCH SỰ TRONG LỚP:\n- [Hành động] + please!\n  + Stand up, please! (Xin mời các em đứng lên!)\n  + Sit down, please! (Xin mời các em ngồi xuống!)\n- Please + [Hành động]!\n  + Please be quiet! (Làm ơn hãy giữ trật tự nhé!)\n  + Please listen to the teacher! (Làm ơn hãy chú ý lắng nghe cô giáo!)\n\n2. HƯỚNG DẪN QUAN SÁT:\n- Look at the board! (Hãy nhìn lên bảng!)\n- Look at me! (Hãy nhìn về phía cô nào!)",
