            order = 1
        ),
        Grammar(
            id = "g_kids_6_3_1",
            lessonId = "lesson_kids_6_3",
            title = "Yes / No Questions with 'Is this a...?'",
            titleVi = "Câu hỏi Đúng/Sai với 'Is this a...?'",
            explanation = "Ask 'Is this a...?' and answer 'Yes, it is' or 'No, it isn't'.",
            explanationVi = "1. HỎI ĐÂY CÓ PHẢI LÀ MỘT ĐỒ VẬT NÀO ĐÓ KHÔNG:\n- Is this a/an + [Đồ vật]?\n  + Ví dụ: Is this a pencil? (Đây có phải là chiếc bút chì không?)\n\n2. CÁCH TRẢ LỜI:\n- Nếu ĐÚNG: Yes, it is. (Vâng, đúng rồi.)\n- Nếu KHÔNG ĐÚNG: No, it isn't. (Không, không phải đâu.)\n  + Bé có thể nói thêm câu đính chính: No, it isn't. It is a pen. (Không phải, nó là một cây bút mực.)",
            examples = listOf("Is this a ruler? - Yes, it is.", "Is this a book? - No, it isn't. It is a notebook.", "Let's cut paper and draw!"),
