    fun getUnit7Grammars(): List<Grammar> = listOf(
        Grammar(
            id = "g_kids_7_1_1",
            lessonId = "lesson_kids_7_1",
            title = "Animal Sounds and 'It is a...'",
            titleVi = "Miêu tả con vật và tiếng kêu dễ thương",
            explanation = "Use 'It is a...' to name the animal, and add action words.",
            explanationVi = "1. GỌI TÊN CON VẬT:\n- What is it? (Đó là con gì thế?)\n- Trả lời: It is a + [Tên con vật].\n  + It is a duck. (Đó là một con vịt.)\n  + It is a cow. (Đó là một con bò sữa.)\n\n2. TIẾNG KÊU CỦA CON VẬT:\n- The dog says woof woof! (Chú cún sủa gâu gâu!)\n- The cat says meow meow! (Chú mèo kêu meo meo!)\n- The duck says quack quack! (Chú vịt kêu cạp cạp!)\n- The cow says moo moo! (Chú bò kêu ùm bò!)",
            examples = listOf("What is it? - It is a pink pig.", "The cow says moo!", "The duck can swim in the pond."),
            examplesVi = listOf("Đó là con gì thế? - Đó là một chú lợn màu hồng.", "Bác bò sữa kêu ùm bò!", "Bạn vịt có thể bơi lội dưới ao."),
            order = 1
        ),
        Grammar(
            id = "g_kids_7_2_1",
            lessonId = "lesson_kids_7_2",
            title = "Can and Can't for Animal Abilities",
            titleVi = "Nói về khả năng của con vật với 'Can' (có thể) và 'Can't' (không thể)",
            explanation = "Use 'A bird can fly' or 'An elephant cannot climb trees'.",
            explanationVi = "1. DIỄN TẢ KHẢ NĂNG (CÓ THỂ LÀM GÌ):\n- [Chủ ngữ] + can + [Hành động].\n  + A bird can fly. (Một chú chim có thể bay lượn.)\n  + A monkey can climb trees. (Một chú khỉ có thể leo trèo cây.)\n  + A kangaroo can jump high. (Một chú chuột túi có thể nhảy rất cao.)\n\n2. DIỄN TẢ KHÔNG THỂ LÀM GÌ:\n- [Chủ ngữ] + cannot (can't) + [Hành động].\n  + An elephant can't fly. (Một chú voi không thể bay được.)\n  + A fish can't walk. (Một chú cá không thể đi bộ được.)",
            examples = listOf("A bird can fly in the sky.", "A monkey can climb tall trees.", "An elephant cannot fly."),
            examplesVi = listOf("Một chú chim có thể bay lượn trên bầu trời.", "Một chú khỉ có thể leo lên những cây cao vút.", "Một chú voi thì không thể bay được."),
            order = 1
        ),
        Grammar(
            id = "g_kids_7_3_1",
            lessonId = "lesson_kids_7_3",
            title = "Describing Nature with 'The ... is ...'",
            titleVi = "Miêu tả cảnh vật thiên nhiên với 'The ... is ...'",
            explanation = "Use 'The sun is yellow' and 'The flowers are colorful'.",
            explanationVi = "1. MIÊU TẢ CẢNH VẬT THIÊN NHIÊN (SỐ ÍT):\n- The + [Cảnh vật số ít] + is + [Tính từ].\n  + The sun is bright and yellow. (Mặt trời sáng rực và vàng ấm.)\n  + The sky is blue. (Bầu trời trong xanh ngắt.)\n  + The moon is silver. (Mặt trăng màu bạc vằng vặc.)\n\n2. MIÊU TẢ CẢNH VẬT (SỐ NHIỀU):\n- The + [Cảnh vật số nhiều] + are + [Tính từ].\n  + The flowers are beautiful. (Những bông hoa thật xinh đẹp.)\n  + The stars are bright. (Những vì sao thật sáng lấp lánh.)",
            examples = listOf("The sun is bright and warm.", "The blue sky is clear.", "The flowers are so beautiful!"),
            examplesVi = listOf("Mặt trời thật rực rỡ và ấm áp.", "Bầu trời xanh trong vắt.", "Những bông hoa trông thật xinh đẹp làm sao!"),
            order = 1
        )
    )

