            examples = listOf("I like apples and bananas.", "I don't like sour oranges.", "Watermelon is sweet and cool."),
            examplesVi = listOf("Mình rất thích táo và chuối.", "Mình không thích những quả cam bị chua.", "Dưa hấu vừa ngọt vừa mát rượi."),
            order = 1
        ),
        Grammar(
            id = "g_kids_8_2_1",
            lessonId = "lesson_kids_8_2",
            title = "Asking 'Do you like...?'",
            titleVi = "Hỏi bạn thích món gì với 'Do you like...?'",
            explanation = "Ask 'Do you like milk?' and answer 'Yes, I do' or 'No, I don't'.",
            explanationVi = "1. HỎI BẠN CÓ THÍCH MÓN GÌ ĐÓ KHÔNG:\n- Do you like + [Tên món ăn / Đồ uống]?\n  + Do you like milk? (Bạn có thích uống sữa không?)\n  + Do you like fish? (Bạn có thích ăn cá không?)\n\n2. CÁCH TRẢ LỜI:\n- Nếu CÓ THÍCH: Yes, I do! (Có, mình thích lắm!)\n- Nếu KHÔNG THÍCH: No, I don't. (Không, mình không thích lắm.)\n\n3. LƯU Ý TỪ KHÔNG ĐẾM ĐƯỢC:\n- Các từ như milk, water, rice, soup không thêm 's' ở dạng số nhiều bé nhé!",
            examples = listOf("Do you like milk? - Yes, I do!", "Do you like fish? - No, I don't. I like chicken.", "Drink plenty of water every day."),
            examplesVi = listOf("Bạn có thích uống sữa không? - Có, mình thích lắm!", "Bạn có thích ăn cá không? - Không, mình thích thịt gà hơn.", "Hãy uống nhiều nước lọc mỗi ngày nhé."),
            order = 1
        ),
        Grammar(
            id = "g_kids_8_3_1",
            lessonId = "lesson_kids_8_3",
            title = "Polite Requests with 'I want ... please'",
            titleVi = "Đưa ra yêu cầu lịch sự với 'I want ... please'",
            explanation = "Say 'I want ice cream, please!' to ask politely for treats.",
            explanationVi = "1. YÊU CẦU LỊCH SỰ VỚI 'PLEASE':\n- I want + [Món ăn / Đồ vật] + please!\n  + I want ice cream, please! (Làm ơn cho con xin kem ạ!)\n  + I want a cookie, please! (Làm ơn cho con xin một chiếc bánh quy ạ!)\n\n2. KHEN NGỢI MÓN ĂN NGON:\n- It is yummy! (Nó ngon tuyệt cú mèo!)\n- It is delicious! (Món này thơm ngon quá đi!)\n\n3. LƯU Ý SỨC KHỎE:\n- Kem và kẹo rất ngon nhưng bé nhớ ăn vừa phải và đánh răng sạch sau khi ăn nhé!",
