            explanationVi = "1. KHI NHẬN ĐƯỢC LỜI CẢM ƠN:\n- Khi ai đó nói 'Thank you!', bé hãy đáp lại lịch sự:\n  + You're welcome! (Không có chi đâu bạn!)\n\n2. KHI MUỐN XIN LỖI:\n- I am sorry! / Sorry! (Mình xin lỗi nhé!)\n- Người kia sẽ mỉm cười và đáp:\n  + It's okay! / That's all right! (Không sao đâu bạn!)\n\n3. KHI CẦN XIN PHÉP HOẶC NHỜ CHÚ Ý:\n- Excuse me! (Xin thứ lỗi / Xin lỗi cho mình hỏi một chút nhé!)",
            examples = listOf("Thank you! - You're welcome!", "I am sorry! - That's okay!", "Excuse me, can you help me?"),
            examplesVi = listOf("Cảm ơn bạn nhé! - Không có chi đâu!", "Mình xin lỗi bạn nhé! - Không sao đâu mà!", "Xin lỗi, bạn có thể giúp mình một chút không?"),
            order = 1
        ),
        Grammar(
            id = "g_kids_10_2_1",
            lessonId = "lesson_kids_10_2",
            title = "Prepositions: In, On, Under",
            titleVi = "Giới từ chỉ nơi chốn: In (trong), On (trên), Under (dưới)",
            explanation = "Ask 'Where is...?' and answer with in, on, or under.",
            explanationVi = "1. HỎI VỊ TRÍ ĐỒ VẬT:\n- Where is the + [Đồ vật]? (Đồ vật đó đang ở đâu thế?)\n  + Where is the ball? (Quả bóng đang ở đâu?)\n  + Where is the cat? (Chú mèo đang ở đâu?)\n\n2. CÂU TRẢ LỜI VỚI GIỚI TỪ:\n- It is in the box. (Nó ở TRONG chiếc hộp.)\n- It is on the table. (Nó ở TRÊN bàn.)\n- It is under the chair. (Nó ở DƯỚI gầm ghế.)\n\n3. LƯU Ý GHI NHỚ HÌNH ẢNH:\n- In = bên trong, lọt vào lòng đồ vật.\n- On = bên trên bề mặt tiếp xúc.\n- Under = ở phía dưới, gầm.",
            examples = listOf("Where is the ball? - It is under the chair.", "The pencil is in my schoolbag.", "The book is on the desk."),
            examplesVi = listOf("Quả bóng ở đâu thế? - Nó ở dưới gầm chiếc ghế.", "Cây bút chì đang ở trong cặp sách của mình.", "Quyển sách đang ở trên bàn học."),
            order = 1
        ),
        Grammar(
            id = "g_kids_10_3_1",
            lessonId = "lesson_kids_10_3",
            title = "Confidence: 'I can speak English!'",
            titleVi = "Tự tin khẳng định bản thân: 'I can speak English!'",
            explanation = "Celebrate your journey and confidently speak English everywhere.",
            explanationVi = "1. TỰ TIN KHẲNG ĐỊNH BẢN THÂN:\n- I can speak English! (Con có thể nói được tiếng Anh!)\n- I can listen and understand! (Con có thể lắng nghe và hiểu được!)\n- I am an English superstar! (Con là một ngôi sao tiếng Anh nhí!)\n\n2. LỜI KHÍCH LỆ VÀ ĂN MỪNG:\n- We did it! (Chúng ta đã làm được rồi!)\n- Congratulations! (Nhiệt liệt chúc mừng bé đã hoàn thành xuất sắc toàn bộ 10 Unit chương trình Tiếng Anh Trẻ Em!)",
